from collections import deque

def component_contains_only_3s(grid, start_r, start_c, rows, cols):
    """Check if the 3-connected component of 3s from start contains only 3s"""
    component = []
    queue = deque([(start_r, start_c)])
    visited = set([(start_r, start_c)])

    while queue:
        r, c = queue.popleft()
        component.append((r, c))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if 0 <= r+dr < rows and 0 <= c+dc < cols and grid[r+dr][c+dc] == 0:
                    return False  # Found a 0 in the connected component
                visited.add((nr, nc))
                queue.append((nr, nc))

