# New theory: 
# 1. 0s stay 0 EXCEPT when adjacent to a 3 and that 3 is going to become 1
# 2. 1s become 0
# 3. 2s become 1 if all 8-neighbor cells are 3 (ignoring the 2 itself)
# 4. 3s become 1 if any of their 8-neighbor cells is a 2 that becomes 1
# 5. 3s adjacent to remaining 2s become 2
# 6. Everything else stays 3

def transform_v6(input_grid, rows, cols):
    """Multi-pass implementation"""
    # First pass: find all 2s that become 1
    two_to_one_positions = []
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 2:
                # Check if all 8 neighbors are 3
                all_8_are_3 = True
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        if abs(dr) + abs(dc) == 1:  # Orthogonal doesn't count
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < rows and 0 <= nc < cols and input_grid[nr][nc] != 3:
                                all_8_are_3 = False
                                break
