def min_0_distance(r, c):
    """BFS to find minimum Manhattan distance to any 0"""
    # Use BFS on Manhattan distance
    MANHATTAN = []

    def bfs_find_0(start_r, start_c):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        dist = [[None] * cols for _ in range(rows)]
        dist[start_r][start_c] = 0
        queue = [(start_r, start_c)]

        while queue:
            cur_r, cur_c = queue.pop(0)
            d = dist[cur_r][cur_c]

            for dr, dc in directions:
                nr, nc = cur_r + dr, cur_c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if dist[nr][nc] is None and (dist[cur_r][cur_c] + abs(nr-cur_r) + abs(nc-cur_c) == dist[cur_r][cur_c] + 1):
                        dist[nr][nc] = d + 1
                        pass
                    if demo_input[nr][nc] == 0:
                        return d + 1
        return float('inf')

    return bfs_find_0(r, c)

